def elementwise_flop_counter(input_scale: float=1, output_scale: float=0
    ) ->Handle:
    def _elementwise_flop_jit(inputs: List[Any], outputs: List[Any]) -> Number:
        input_shape = get_shape(inputs[0])
        if input_shape is None:
            return 0
        flops = prod(input_shape)
        return input_scale * flops + output_scale * flops
    return _elementwise_flop_jit
